import numpy as np

def can_fit(Y, D, n_max=10):
    y = [0.0]
    for n in range(2, n_max + 1):
        possible_y = []
        # Try some candidate values for y_n
        # Since we want to maximize D, we can try to place y_n as small as possible
        # but it must be at least D/(m+n) away from all previous y_m.
        # We can check values in a fine grid.
        grid = np.linspace(0, Y, 1000)
        for val in grid:
            if all(abs(val - y[m-1]) >= D / (m + n) for m in range(1, n)):
                y.append(val)
                break
        else:
            return False
    return True

for D in np.linspace(0, 1, 100):
    if can_fit(1.0, D):
        print(f"D={D:.4f} is possible")

import itertools

def solve_sk(k):
    min_sum = float('inf')
    for p in itertools.permutations(range(1, k + 1)):
        current_sum = 0
        for i in range(k - 1):
            current_sum += 1 / (p[i] + p[i+1])
        if current_sum < min_sum:
            min_sum = current_sum
    return min_sum

for k in range(2, 8):
    print(f"S_{k} = {solve_sk(k)}")

import numpy as np

def can_fit_greedy(Y, D, n_max=1000):
    y = [0.0]
    for n in range(2, n_max + 1):
        intervals = []
        for m in range(1, n):
            L = y[m-1] - D / (m + n)
            R = y[m-1] + D / (m + n)
            if R > 0 and L < Y:
                intervals.append((max(0, L), min(Y, R)))

        intervals.sort()

        # Merge intervals
        merged = []
        if intervals:
            curr_L, curr_R = intervals[0]
            for i in range(1, len(intervals)):
                next_L, next_R = intervals[i]
                if next_L < curr_R:
                    curr_R = max(curr_R, next_R)
                else:
                    merged.append((curr_L, curr_R))
                    curr_L, curr_R = next_L, next_R
            merged.append((curr_L, curr_R))

        # Find the first gap
        found_y = -1
        if not merged:
            found_y = 0.0
        else:
            if merged[0][0] > 0:
                found_y = 0.0
            else:
                for i in range(len(merged)):
                    # Check if there's a gap after this interval
                    if i + 1 < len(merged):
                        if merged[i+1][0] > merged[i][1]:
                            found_y = merged[i][1]
                            break
                    else:
                        if merged[i][1] < Y:
                            found_y = merged[i][1]
                            break

        if found_y != -1 and found_y <= Y:
            y.append(found_y)
        else:
            return False
    return True

