import numpy as np
from scipy.optimize import linprog

def solve_min_sum(n):
    # s_1, s_2, ..., s_{n-1}
    # Variables: s_1, ..., s_{n-1}
    # Objective: min sum(s_i)
    # Constraints:
    # sum_{i=j}^{k-1} s_i >= 1 / (j+k)  =>  -sum_{i=j}^{k-1} s_i <= -1 / (j+k)
    # s_i >= 0

    c = np.ones(n-1)
    A_ub = []
    b_ub = []

    for j in range(1, n):
        for k in range(j+1, n+1):
            # Constraint: sum_{i=j}^{k-1} s_i >= 1 / (j+k)
            # The variables are s_1, ..., s_{n-1}
            # So the indices for s_i are i-1 (from 0 to n-2)
            # The sum is over s_j, ..., s_{k-1}
            # So indices are j-1, ..., k-2
            row = np.zeros(n-1)
            for i in range(j, k):
                row[i-1] = -1
            A_ub.append(row)
            b_ub.append(-1 / (j+k))

    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=(0, None), method='highs')
    return res.fun

for n in range(2, 30):
    print(f"n={n}: {solve_min_sum(n)}")

import math

def calculate_S_k_limit_approx(k):
    # The minimum sum is at least H_{2k-1} - H_k
    # which is approx ln(2k-1) - ln(k) = ln((2k-1)/k) -> ln 2
    return math.log(2)

