def find_sequence(Y, D, n_max=1000):
    y = [0.0]
    for n in range(2, n_max + 1):
        intervals = []
        for m in range(1, n):
            L = y[m-1] - D / (m + n)
            R = y[m-1] + D / (m + n)
            if R > 0 and L < Y:
                intervals.append((max(0.0, L), min(Y, R)))

        intervals.sort()
        merged = []
        if intervals:
            curr_L, curr_R = intervals[0]
            for i in range(1, len(intervals)):
                next_L, next_R = intervals[i]
                if next_L < curr_R:
                    curr_R = max(curr_R, next_R)
                else:
                    merged.append((curr_L, curr_R))
                    curr_L, curr_R = next_L, next_R
            merged.append((curr_L, curr_R))

        found_y = -1
        if not merged:
            found_y = 0.0
        else:
            if merged[0][0] > 0:
                found_y = 0.0
            else:
                for i in range(len(merged)):
                    if i + 1 < len(merged):
                        if merged[i+1][0] > merged[i][1]:
                            found_y = merged[i][1]
                            break
                    else:
                        if merged[i][1] < Y:
                            found_y = merged[i][1]
                            break

        if found_y != -1 and found_y <= Y:
            y.append(found_y)
        else:
            return y, n
    return y, n_max + 1

