def solve_Sk(k):
    # Nodes are 1, ..., k
    # dp[mask][i] is the min sum for visiting nodes in mask, ending at node i
    # mask is a bitmask of length k, where bit j represents node j+1
    # dp table initialized to infinity
    dp = [[float('inf')] * (k + 1) for _ in range(1 << k)]

    # Base cases: starting with any node i
    for i in range(1, k + 1):
        dp[1 << (i - 1)][i] = 0

    for mask in range(1, 1 << k):
        for i in range(1, k + 1):
            if dp[mask][i] == float('inf'):
                continue
            # Try moving to node j
            for j in range(1, k + 1):
                if not (mask & (1 << (j - 1))):
                    new_mask = mask | (1 << (j - 1))
                    cost = 1 / (i + j)
                    if dp[new_mask][j] > dp[mask][i] + cost:
                        dp[new_mask][j] = dp[mask][i] + cost

    ans = float('inf')
    full_mask = (1 << k) - 1
    for i in range(1, k + 1):
        ans = min(ans, dp[full_mask][i])
    return ans

