def solve_sk_tsp(k):
    G = nx.Graph()
    for i in range(1, k + 1):
        for j in range(i + 1, k + 1):
            G.add_edge(i, j, weight=1/(i+j))

    # We want the minimum weight Hamiltonian Path.
    # This is NP-hard, but for small k we can use Held-Karp.
    # Wait, there's no specific start or end node.

    # Use a simple TSP solver or just Held-Karp.
    # Let's use Held-Karp.
    n = k
    # distance matrix
    dist = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                dist[i][j] = float('inf')
            else:
                dist[i][j] = 1 / ((i+1) + (j+1))

    # dp[mask][i] is the min cost to visit nodes in mask, ending at i
    dp = [[float('inf')] * n for _ in range(1 << n)]

    for i in range(n):
        dp[1 << i][i] = 0

    for mask in range(1, 1 << n):
        for i in range(n):
            if dp[mask][i] == float('inf'):
                continue
            for j in range(n):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    dp[new_mask][j] = min(dp[new_mask][j], dp[mask][i] + dist[i][j])

