def get_min_range_for_D1(k):
    min_range = float('inf')
    for p in itertools.permutations(range(1, k + 1)):
        y = [0] * k
        # y[i] is the value for the i-th smallest position in our sorted list
        # No, the indices in p are the original positions in the sequence.
        # So y[i] corresponds to position p[i].
        # The sorted values are y_sorted[0] < y_sorted[1] < ... < y_sorted[k-1]
        # Let's re-think.
        # We want to find a sequence y_1, ..., y_k such that |y_n - y_m| >= 1/(n+m).
        # This is equivalent to finding a permutation sigma of {1, ..., k}
        # such that y_{sigma(1)} < y_{sigma(2)} < ... < y_{sigma(k)}
        # and y_{sigma(j)} - y_{sigma(i)} >= 1 / (sigma(j) + sigma(i)).
        # Then the minimum range is y_{sigma(k)} - y_{sigma(1)}.

        # p is the permutation of indices such that y_{p[0]} < y_{p[1]} < ... < y_{p[k-1]}
        # So the values are y_{p[0]}, y_{p[1]}, ..., y_{p[k-1]}
        # Let v[j] = y_{p[j]}.
        # v[0] = 0
        # v[j] = max_{i < j} (v[i] + 1 / (p[i] + p[j]))

        v = [0] * k
        for j in range(1, k):
            max_val = 0
            for i in range(j):
                max_val = max(max_val, v[i] + 1 / (p[i] + p[j]))
            v[j] = max_val

        if v[k-1] < min_range:
            min_range = v[k-1]
    return min_range

