    y = [0.0] * (k + 1)
    y[1] = 0.0
    for n in range(2, k + 1):
        forbidden = []
        for m in range(1, n):
            forbidden.append((y[m] - D/(n+m), y[m] + D/(n+m)))

        forbidden.sort()

        best_y = 0.0
        merged = []
        if forbidden:
            curr_L, curr_R = forbidden[0]
            for i in range(1, len(forbidden)):
                next_L, next_R = forbidden[i]
                if next_L < curr_R:
                    curr_R = max(curr_R, next_R)
                else:
                    merged.append((curr_L, curr_R))
                    curr_L, curr_R = next_L, next_R
            merged.append((curr_L, curr_R))

        for L, R in merged:
            if L < best_y < R:
                best_y = R

        if best_y > M:
            return False
        y[n] = best_y
    return True

