            candidates = []
            for m in range(1, n):
                val = y[m-1] + D / (n + m)
                if val > lower_bound + 1e-9:
                    candidates.append(val)
            candidates.sort()
            found = False
            for cand in candidates:
                is_cand_valid = True
                for m_idx in range(1, n):
                    if abs(cand - y[m_idx-1]) < D / (n + m_idx) - 1e-9:
                        is_cand_valid = False
                        break
                if is_cand_valid:
                    y.append(cand)
                    found = True
                    break
            if not found:
                return False
        if y[-1] > M:
            return False
    return True

def find_max_D_greedy(M, k=200):
    low = 0.0
    high = M
    # We want to find the largest D such that can_build_sequence_greedy(D, M, k) is True.
    # Since it's monotonic, we can use binary search.
    for _ in range(40):
        mid = (low + high) / 2
        if can_build_sequence_greedy(mid, M, k):
            low = mid
        else:
            high = mid
    return low

print(f"Max D for M=1: {find_max_D_greedy(1.0)}")

def can_build_sequence_best_fit_v2(D, M, k=100):
    y = []
    for n in range(1, k + 1):
        # Excluded intervals
        intervals = []
        for m in range(1, n):
            l = y[m-1] - D / (n + m)
            r = y[m-1] + D / (n + m)
            intervals.append((l, r))

        intervals.sort()
        merged = []
        if intervals:
            curr_l, curr_r = intervals[0]
            for i in range(1, len(intervals)):
                next_l, next_r = intervals[i]
                if next_l < curr_r:
                    curr_r = max(curr_r, next_r)
                else:
                    merged.append((curr_l, curr_r))
                    curr_l, curr_r = next_l, next_r
            merged.append((curr_l, curr_r))

        target = M / 2.0
        found_y = None
        is_target_free = True
        for l, r in merged:
            if l < target < r:
                is_target_free = False
                break

        if is_target_free:
            if 0 <= target <= M:
                found_y = target
            else:
                if target < 0: found_y = 0
                else: found_y = M
        else:
            candidates = []
            for l, r in merged:
                if l >= 0 and l <= M:
                    candidates.append(l)
                if r >= 0 and r <= M:
                    candidates.append(r)
            candidates.append(0.0)
            candidates.append(M)

            valid_candidates = []
            for c in candidates:
                is_c_free = True
                for l, r in merged:
                    if l < c < r:
                        is_c_free = False
                        break
                if is_c_free:
                    valid_candidates.append(c)

            if not valid_candidates:
                return False
            best_c = min(valid_candidates, key=lambda x: abs(x - target))
            found_y = best_c

        if found_y is None:
            return False
        y.append(found_y)
        if y[-1] < 0 or y[-1] > M:
            return False
    return True

def find_max_D_best_fit_v2(M, k=100):
    low = 0.0
    high = M
    for _ in range(30):
        mid = (low + high) / 2
        if can_build_sequence_best_fit_v2(mid, M, k):
            low = mid
        else:
            high = mid
    return low

print(f"Max D for M=1: {find_max_D_best_fit_v2(1.0)}")

